module tb_TopModule;
    logic clk;
    logic reset;
    logic w;
    logic z;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .w(w),
        .z(z)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        w = 0;
        #12;
        reset = 0;

        // Test sequence
        // A -> (w=1) -> B -> (w=1) -> C -> (w=1) -> E -> (w=1) -> E (z=1)
        @(posedge clk); w = 1; // A to B
        @(posedge clk); w = 1; // B to C
        @(posedge clk); w = 1; // C to E
        @(posedge clk); w = 1; // E to E (z should be 1)
        #1;
        if (z !== 1) begin
            $display("SELFTEST FAIL: Expected z=1 in state E, got %b", z);
            $finish;
        end

        // E -> (w=0) -> D -> (w=1) -> F (z=1)
        @(posedge clk); w = 0; // E to D
        @(posedge clk); w = 1; // D to F (z should be 1)
        #1;
        if (z !== 1) begin
            $display("SELFTEST FAIL: Expected z=1 in state F, got %b", z);
            $finish;
        end

        // F -> (w=1) -> C -> (w=0) -> D -> (w=0) -> A
        @(posedge clk); w = 1; // F to C (z=0)
        #1;
        if (z !== 0) begin
            $display("SELFTEST FAIL: Expected z=0 in state C, got %b", z);
            $finish;
        end
        @(posedge clk); w = 0; // C to D
        @(posedge clk); w = 0; // D to A

        // Test reset
        @(posedge clk); reset = 1; w = 1;
        @(posedge clk); reset = 0;
        #1;
        // Should be in A, state table w=1 goes to B next cycle
        @(posedge clk);
        #1;
        // Now in B, next w=0 goes to D
        @(posedge clk); w = 0;
        @(posedge clk);
        #1;
        // In D, w=0 goes to A
        @(posedge clk); w = 0;
        @(posedge clk);
        #1;
        // In A, w=0 stays in A
        if (z !== 0) begin
            $display("SELFTEST FAIL: Expected z=0 in state A, got %b", z);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

